class Solution:
    def placedCoins(self, edges, cost):
        n = len(cost)
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        order, par = [0], [-1] * n
        for u in order:
            for v in adj[u]:
                if v != par[u]:
                    par[v] = u
                    order.append(v)
        big = [None] * n
        small = [None] * n
        sz = [1] * n
        ans = [0] * n
        for u in reversed(order):
            b, s = [cost[u]], [cost[u]]
            for v in adj[u]:
                if v != par[u]:
                    b.extend(big[v])
                    s.extend(small[v])
                    sz[u] += sz[v]
            b.sort(reverse=True)
            s.sort()
            big[u], small[u] = b[:3], s[:2]
            if sz[u] < 3:
                ans[u] = 1
            else:
                p = b[0] * b[1] * b[2]
                q = s[0] * s[1] * b[0]
                ans[u] = max(p, q) if max(p, q) > 0 else 0
        return ans

