class Solution {
public:
    vector<long long> placedCoins(vector<vector<int>>& edges, vector<int>& cost) {
        int n = cost.size();
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        vector<int> order, par(n, -1);
        order.push_back(0);
        for (int i = 0; i < (int)order.size(); i++) {
            int u = order[i];
            for (int v : adj[u]) if (v != par[u]) { par[v] = u; order.push_back(v); }
        }
        vector<vector<long long>> big(n), small(n);
        vector<int> sz(n, 1);
        vector<long long> ans(n);
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            vector<long long> b{cost[u]}, s{cost[u]};
            for (int v : adj[u]) if (v != par[u]) {
                b.insert(b.end(), big[v].begin(), big[v].end());
                s.insert(s.end(), small[v].begin(), small[v].end());
                sz[u] += sz[v];
            }
            sort(b.rbegin(), b.rend());
            sort(s.begin(), s.end());
            b.resize(min((int)b.size(), 3));
            s.resize(min((int)s.size(), 2));
            big[u] = b; small[u] = s;
            if (sz[u] < 3) ans[u] = 1;
            else {
                long long p = b[0] * b[1] * b[2];
                long long q = s[0] * s[1] * b[0];
                long long best = max(p, q);
                ans[u] = best > 0 ? best : 0;
            }
        }
        return ans;
    }
};

