class Solution {
    public long[] placedCoins(int[][] edges, int[] cost) {
        int n = cost.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        List<Integer> order = new ArrayList<>();
        int[] par = new int[n];
        Arrays.fill(par, -1);
        order.add(0);
        for (int i = 0; i < order.size(); i++) {
            int u = order.get(i);
            for (int v : adj.get(u)) if (v != par[u]) { par[v] = u; order.add(v); }
        }
        List<Long>[] big = new List[n], small = new List[n];
        int[] sz = new int[n];
        Arrays.fill(sz, 1);
        long[] ans = new long[n];
        for (int i = n - 1; i >= 0; i--) {
            int u = order.get(i);
            List<Long> b = new ArrayList<>(List.of((long) cost[u]));
            List<Long> s = new ArrayList<>(List.of((long) cost[u]));
            for (int v : adj.get(u)) if (v != par[u]) {
                b.addAll(big[v]); s.addAll(small[v]); sz[u] += sz[v];
            }
            b.sort(Collections.reverseOrder());
            Collections.sort(s);
            big[u] = new ArrayList<>(b.subList(0, Math.min(3, b.size())));
            small[u] = new ArrayList<>(s.subList(0, Math.min(2, s.size())));
            if (sz[u] < 3) ans[u] = 1;
            else {
                long p = b.get(0) * b.get(1) * b.get(2);
                long q = s.get(0) * s.get(1) * b.get(0);
                long best = Math.max(p, q);
                ans[u] = best > 0 ? best : 0;
            }
        }
        return ans;
    }
}

