var placedCoins = function(edges, cost) {
    const n = cost.length;
    const adj = Array.from({length: n}, () => []);
    for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
    const order = [0], par = new Array(n).fill(-1);
    for (let i = 0; i < order.length; i++) {
        const u = order[i];
        for (const v of adj[u]) if (v !== par[u]) { par[v] = u; order.push(v); }
    }
    const big = [], small = [], sz = new Array(n).fill(1), ans = new Array(n);
    for (let i = n - 1; i >= 0; i--) {
        const u = order[i];
        let b = [cost[u]], s = [cost[u]];
        for (const v of adj[u]) if (v !== par[u]) {
            b = b.concat(big[v]); s = s.concat(small[v]); sz[u] += sz[v];
        }
        b.sort((x, y) => y - x); s.sort((x, y) => x - y);
        big[u] = b.slice(0, 3); small[u] = s.slice(0, 2);
        if (sz[u] < 3) ans[u] = 1;
        else {
            const p = BigInt(b[0]) * BigInt(b[1]) * BigInt(b[2]);
            const q = BigInt(s[0]) * BigInt(s[1]) * BigInt(b[0]);
            const best = p > q ? p : q;
            ans[u] = best > 0n ? Number(best) : 0;
        }
    }
    return ans;
};
